FUNCTION_BLOCK FB_StripAnnealing_RadiantTubeDewpoint
(*
====================================================================================================
SYSTEM IDENTIFICATION & METADATA
====================================================================================================
Project           : Lumina High-Performance Industrial Automation Kernel
Unit / Plant Area : Continuous Annealing Line (CAL) / Continuous Galvanizing Line (CGL)
Sub-System        : Radiant Tube Heating Section (RHS) NOx Abatement & H2 Protective Atmosphere Control
Target Platform   : IEC 61131-3 Compliant Industrial PLC (CoDeSys v3.5 / TwinCAT 3 / Siemens S7-1500)
Architecture      : Triple Modular Redundant (TMR 2oo3) Sensor Fusion + 2x2 MIMO State-Space MPC
Safety Integrity  : Designed for EN 746-2 (Industrial Thermoprocessing) & NFPA 86D Atmosphere Safety
Author            : Principal Automation Fellow & Cyber-Physical Systems Chair (Lumina AI Swarm)
Revision          : 7.4.2-ST
====================================================================================================
*)

VAR_INPUT
    (* ============================================================================================= *)
    (* LINE SUPERVISORY & EMERGENCY SHUTDOWN SIGNALS                                                *)
    (* ============================================================================================= *)
    bSystemEnable                   : BOOL;     (* Master function block execution enable *)
    bEmergencyStopOk                : BOOL;     (* SIL-3 Safety Circuit Healthy / E-Stop Closed (Active High) *)
    bAtmospherePurgePermit          : BOOL;     (* Permissive from Burner Management System (BMS) for N2/H2 flow *)
    bFurnaceDoorsClosed             : BOOL;     (* Snout and Entry/Exit roll chamber seal closed status *)
    bBurnerSystemRunning            : BOOL;     (* Master burner header status from combustion safety PLC *)

    (* ============================================================================================= *)
    (* STRIP KINEMATICS & PRODUCTION SCHEDULE INPUTS                                                *)
    (* ============================================================================================= *)
    rStripSpeed                     : REAL;     (* Line process strip speed [m/min] (0.0 .. 300.0) *)
    rStripThickness                 : REAL;     (* Caliper thickness of moving steel strip [mm] (0.15 .. 3.50) *)
    rStripWidth                     : REAL;     (* Lateral strip width [mm] (600.0 .. 2100.0) *)
    rSteelGradeAlloyFactor          : REAL;     (* Oxidation resistance factor: 1.0=LC, 2.0=IF, 3.5=AHSS/DP [1.0 .. 4.0] *)

    (* ============================================================================================= *)
    (* TRIPLE MODULAR REDUNDANT (TMR 2oo3) ZONE TEMPERATURE SENSORS                                  *)
    (* ============================================================================================= *)
    rFurnaceZoneTemp_TMR1           : REAL;     (* Radiant Tube Zone Temperature Channel A (Pt-Rh Type S) [deg C] *)
    rFurnaceZoneTemp_TMR2           : REAL;     (* Radiant Tube Zone Temperature Channel B (Pt-Rh Type S) [deg C] *)
    rFurnaceZoneTemp_TMR3           : REAL;     (* Radiant Tube Zone Temperature Channel C (Pt-Rh Type S) [deg C] *)

    (* ============================================================================================= *)
    (* TRIPLE MODULAR REDUNDANT (TMR 2oo3) ATMOSPHERE DEW POINT SENSORS                              *)
    (* ============================================================================================= *)
    rDewPoint_TMR1                  : REAL;     (* Chilled Mirror Optical Dewpoint Transducer [deg C] (-80.0 .. 20.0) *)
    rDewPoint_TMR2                  : REAL;     (* Thin-film Al2O3 Capacitive Hygrometer [deg C] (-80.0 .. 20.0) *)
    rDewPoint_TMR3                  : REAL;     (* Tunable Diode Laser Absorption Spec (TDLAS) [deg C] (-80.0 .. 20.0) *)

    (* ============================================================================================= *)
    (* COMBUSTION, STOICHIOMETRY & FLUE GAS EMISSION TRANSDUCERS                                     *)
    (* ============================================================================================= *)
    rExhaustNOx_ppm                 : REAL;     (* Radiant tube common exhaust NOx concentration [ppm] (0.0 .. 500.0) *)
    rExhaustO2_pct                  : REAL;     (* Paramagnetic flue gas residual oxygen [vol %] (0.0 .. 21.0) *)
    rExhaustCO_ppm                  : REAL;     (* Flue gas incomplete combustion carbon monoxide [ppm] (0.0 .. 2000.0) *)
    rCombAirPreheatTemp_degC        : REAL;     (* Central metallic recuperator combustion air temp [deg C] (20 .. 550) *)
    rFuelGasLowerHeatingVal_MJ_Nm3  : REAL;     (* Natural Gas / Mixed Fuel Net Calorific Value [MJ/Nm3] (20.0 .. 45.0) *)
    rFuelGasActualFlow_Nm3h         : REAL;     (* Total metered fuel gas consumption to zone [Nm3/h] (0.0 .. 2500.0) *)
    rCombAirActualFlow_Nm3h         : REAL;     (* Total metered combustion air flow to zone [Nm3/h] (0.0 .. 30000.0) *)

    (* ============================================================================================= *)
    (* FURNACE PROTECTIVE GAS COMPOSITION & STATIC PRESSURE                                          *)
    (* ============================================================================================= *)
    rAtmosphereH2_pct               : REAL;     (* Thermal conductivity analyzer H2 content [vol %] (0.0 .. 100.0) *)
    rAtmosphereN2_Flow_Nm3h         : REAL;     (* Bulk high-purity Nitrogen purge flow [Nm3/h] (0.0 .. 2000.0) *)
    rAtmosphereH2_Flow_Nm3h         : REAL;     (* Pure Hydrogen protective gas flow [Nm3/h] (0.0 .. 500.0) *)
    rFurnacePressure_mbar           : REAL;     (* Differential furnace internal static pressure [mbar] (-2.0 .. +10.0) *)

    (* ============================================================================================= *)
    (* OPERATOR TARGET SETPOINTS & TIMING CONFIGURATION                                             *)
    (* ============================================================================================= *)
    rSetPointZoneTemp_degC          : REAL;     (* Desired annealing zone temperature setpoint [deg C] (600 .. 980) *)
    rSetPointDewPoint_degC          : REAL;     (* Critical dew point ceiling setpoint [deg C] (-65.0 .. -30.0) *)
    rTargetH2_pct                   : REAL;     (* Nominal target hydrogen concentration [vol %] (3.0 .. 75.0) *)
    rNOxPermitCeiling_ppm           : REAL;     (* Regulatory compliance maximum NOx emission limit [ppm] (50 .. 200) *)
    tTaskCycleTime                  : TIME;     (* Deterministic PLC cyclic execution task time [e.g. T#50MS] *)
END_VAR

VAR_OUTPUT
    (* ============================================================================================= *)
    (* SUPERVISORY & SAFETY INTERLOCK STATUS WORDS                                                   *)
    (* ============================================================================================= *)
    bSystemReady                    : BOOL;     (* Block ready and safe for thermal processing *)
    bAtmosphereSafe                 : BOOL;     (* H2/N2 gas blend within non-explosive / protected regime *)
    bEmergencyPurgeActive           : BOOL;     (* Emergency inerting deluge purge commanded *)
    wZoneStatusWord                 : WORD;     (* Packed bitfield reflecting operating state & permissives *)
    dwAlarmBitmask                  : DWORD;    (* Industrial SIL alarm register bitmask *)

    (* ============================================================================================= *)
    (* COMBUSTION & LOW-NOX ACTUATOR DEMANDS                                                         *)
    (* ============================================================================================= *)
    rFuelFlowDemand_Nm3h            : REAL;     (* Modulating fuel gas control valve flow setpoint [Nm3/h] *)
    rAirFlowDemand_Nm3h             : REAL;     (* Modulating combustion air control valve flow setpoint [Nm3/h] *)
    rAirFuelRatioTarget             : REAL;     (* Dynamically biased combustion lambda ratio target [-] *)
    rFGR_DamperPositionDemand_pct   : REAL;     (* Flue Gas Recirculation (FGR) damper command [0.0 .. 100.0 %] *)
    rSecondaryAirSplit_pct          : REAL;     (* Staged air burner secondary air split ratio [0.0 .. 100.0 %] *)
    rDeNOx_ReagentFlowDemand_l_h    : REAL;     (* Selective Non-Catalytic Reduction (SNCR) reagent flow [l/h] *)

    (* ============================================================================================= *)
    (* ATMOSPHERE CONDITIONING & DEW POINT SUPPRESSION ACTUATORS                                     *)
    (* ============================================================================================= *)
    rH2_TrimmingValveDemand_pct     : REAL;     (* Fine-trim modulating H2 injection valve command [0.0 .. 100.0 %] *)
    rDryN2_PurgeValveDemand_pct     : REAL;     (* Rapid dew point depression dry N2 valve demand [0.0 .. 100.0 %] *)
    rAtmosphereExhaustDamper_pct    : REAL;     (* Furnace pressure control venting damper [0.0 .. 100.0 %] *)

    (* ============================================================================================= *)
    (* VALIDATED SENSORS & PROCESS METRICS (CYBER-PHYSICAL OBSERVER OUTPUTS)                         *)
    (* ============================================================================================= *)
    rValidatedZoneTemp_degC         : REAL;     (* 2oo3 TMR Validated Radiant Tube Zone Temperature [deg C] *)
    rValidatedDewPoint_degC         : REAL;     (* 2oo3 TMR Validated Protective Atmosphere Dewpoint [deg C] *)
    rWaterVaporPartialPress_Pa      : REAL;     (* Calculated moisture partial pressure P_H2O [Pa] *)
    rLog10_PH2O_PH2_Ratio           : REAL;     (* Ellingham-Richardson thermodynamic oxidation potential index *)
    rInstantaneousNOx_kg_h          : REAL;     (* Flue gas mass emission rate [kg NOx / hour] *)
    rSpecificEnergy_MJ_ton          : REAL;     (* Specific thermal energy consumption per ton of steel [MJ/t] *)
    iCurrentControlState            : INT;      (* Active finite state machine sequential phase ID *)
END_VAR

VAR
    (* ============================================================================================= *)
    (* 2oo3 TRIPLE MODULAR REDUNDANCY (TMR) OBSERVER & VOTING VARIABLES                              *)
    (* ============================================================================================= *)
    bTMR_Temp_Ch1_Healthy           : BOOL := TRUE;
    bTMR_Temp_Ch2_Healthy           : BOOL := TRUE;
    bTMR_Temp_Ch3_Healthy           : BOOL := TRUE;
    rTMR_Temp_Diff12                : REAL;
    rTMR_Temp_Diff23                : REAL;
    rTMR_Temp_Diff31                : REAL;
    ton_TempDiscrepancy_Ch1         : TON;
    ton_TempDiscrepancy_Ch2         : TON;
    ton_TempDiscrepancy_Ch3         : TON;

    bTMR_Dew_Ch1_Healthy            : BOOL := TRUE;
    bTMR_Dew_Ch2_Healthy            : BOOL := TRUE;
    bTMR_Dew_Ch3_Healthy            : BOOL := TRUE;
    rTMR_Dew_Diff12                 : REAL;
    rTMR_Dew_Diff23                 : REAL;
    rTMR_Dew_Diff31                 : REAL;
    ton_DewDiscrepancy_Ch1          : TON;
    ton_DewDiscrepancy_Ch2          : TON;
    ton_DewDiscrepancy_Ch3          : TON;

    (* ============================================================================================= *)
    (* FINITE STATE MACHINE SEQUENCING & PURGE TIMERS                                               *)
    (* ============================================================================================= *)
    iFurnaceState                   : INT := 0;     (* 0:IDLE, 10:N2_PURGE, 20:TMR_CHECK, 30:HEAT, 40:H2_RAMP, 50:MPC_RUN, 60:SPEED_TRANS, 70:DEGRADED, 80:LINE_IDLE, 90:EMERGENCY *)
    ton_StateTimer                  : TON;
    ton_PurgeTimer                  : TON;
    ton_IgnitionSoak                : TON;
    rCumulativePurgeVolume_Nm3      : REAL := 0.0;
    rRequiredPurgeVolume_Nm3        : REAL := 4500.0; (* 5 furnace volume exchanges *)

    (* ============================================================================================= *)
    (* 2x2 MIMO MODEL PREDICTIVE CONTROL (MPC) RECURSIVE STATE-SPACE VECTORS                         *)
    (* ============================================================================================= *)
    (* States x: [1]=NOx dynamic bias [ppm], [2]=Tube thermal lag [deg C], [3]=Dewpoint moisture rate [ppm/s], [4]=Atmosphere inertia [-] *)
    x1_NOx                          : REAL := 0.0;
    x2_TubeThermal                  : REAL := 0.0;
    x3_MoistureRate                 : REAL := 0.0;
    x4_AtmoInertia                  : REAL := 0.0;

    (* Manipulated variables u: [1]=Lambda trim, [2]=FGR damper [%], [3]=Dry N2 trim flow [Nm3/h] *)
    u1_LambdaTrim                   : REAL := 1.08;
    u2_FGR_Damper                   : REAL := 15.0;
    u3_DryN2_Trim                   : REAL := 50.0;

    (* Disturbances d: [1]=Strip heat absorption throughput [kW], [2]=Speed acceleration [m/min/s] *)
    rStripHeatAbsorption_kW         : REAL := 0.0;
    rSpeedAcceleration              : REAL := 0.0;
    rPrevStripSpeed                 : REAL := 0.0;

    (* Tracking errors and integral accumulators *)
    rErrorZoneTemp                  : REAL := 0.0;
    rErrorDewPoint                  : REAL := 0.0;
    rErrorNOx                       : REAL := 0.0;
    rIntegralTemp                   : REAL := 0.0;
    rIntegralDew                    : REAL := 0.0;
    rIntegralNOx                    : REAL := 0.0;

    (* ============================================================================================= *)
    (* THERMAL NOX ZELDOVICH KINETICS & COMBUSTION RATIO CALCULATORS                                *)
    (* ============================================================================================= *)
    rAdiabaticFlameTemp_K           : REAL := 2100.0;
    rZeldovichNOxFactor             : REAL := 0.0;
    rEstimatedNOx_ppm               : REAL := 0.0;
    rTheoreticalCombAirDemand_Nm3h  : REAL := 0.0;
    rFGR_ThermalDampingEffect       : REAL := 0.0;

    (* ============================================================================================= *)
    (* ATMOSPHERE DEW POINT KINETICS & ELLINGHAM OXIDATION MODEL                                    *)
    (* ============================================================================================= *)
    rSaturationVaporPress_hPa       : REAL := 0.0;
    rEquilibriumLogRatio_Limit      : REAL := 0.0;
    bAlloyOxidationRisk             : BOOL := FALSE;
    rDewPointSuppressionDemand      : REAL := 0.0;

    (* Cycle time in seconds for integration *)
    rCycleTimeSec                   : REAL := 0.050;
    iLoopCounter                    : DINT := 0;
END_VAR

VAR CONSTANT
    (* Physical constants for steel thermodynamics & gas kinetics *)
    STEEL_DENSITY_KG_M3             : REAL := 7850.0;       (* Specific mass of carbon steel [kg/m3] *)
    STEEL_SPECIFIC_HEAT_J_KG_K      : REAL := 650.0;        (* Mean thermal capacity of steel strip [J/(kg*K)] *)
    STOICHIOMETRIC_AIR_FUEL_RATIO   : REAL := 9.52;         (* Stoichiometric air-to-gas ratio for typical CH4 fuel *)
    NOX_MOLAR_MASS_G_MOL            : REAL := 46.0055;      (* Standard NO2 molecular weight for emission inventory *)
    FURNACE_INTERNAL_VOLUME_M3      : REAL := 900.0;        (* Radiant tube heating zone enclosed volume [m3] *)
    TMR_TEMP_MAX_DEVIATION_DEG_C    : REAL := 18.0;         (* Permissible discrepancy limit between thermocouples *)
    TMR_DEW_MAX_DEVIATION_DEG_C     : REAL := 6.5;          (* Permissible discrepancy limit between dewpoint analyzers *)
    DISCREPANCY_PERSIST_TIME        : TIME := T#3S;         (* Persistence filter duration before channel isolation *)
END_VAR

(* ================================================================================================= *)
(* EXECUTION START: CYCLIC DETERMINISTIC LOGIC                                                       *)
(* ================================================================================================= *)

(* Calculate floating cycle time from TIME structure *)
rCycleTimeSec := TIME_TO_REAL(tTaskCycleTime) / 1000.0;
IF rCycleTimeSec <= 0.001 THEN
    rCycleTimeSec := 0.050; (* Safe fallback default 50ms *)
END_IF;

iLoopCounter := iLoopCounter + 1;

(* ================================================================================================= *)
(* 1. SIL-3 SAFETY INTERLOCKS & HARDWARE FAILS-SAFE CHECK                                            *)
(* ================================================================================================= *)
IF (NOT bEmergencyStopOk) OR (NOT bSystemEnable) THEN
    (* Immediate failsafe de-energization *)
    bSystemReady                 := FALSE;
    bAtmosphereSafe              := FALSE;
    bEmergencyPurgeActive        := TRUE;
    rFuelFlowDemand_Nm3h         := 0.0;
    rAirFlowDemand_Nm3h          := 250.0; (* Minimum scavenging air for flue purging *)
    rFGR_DamperPositionDemand_pct:= 0.0;
    rSecondaryAirSplit_pct       := 0.0;
    rDeNOx_ReagentFlowDemand_l_h := 0.0;
    rH2_TrimmingValveDemand_pct  := 0.0;
    rDryN2_PurgeValveDemand_pct  := 100.0; (* Full deluge nitrogen sweep *)
    rAtmosphereExhaustDamper_pct := 100.0; (* Full furnace stack vent open *)

    dwAlarmBitmask := dwAlarmBitmask OR 16#00000001; (* Bit 0: Emergency Trip Latched *)
    iFurnaceState  := 90;                           (* Transition to EMERGENCY deluge state *)
END_IF;

(* ================================================================================================= *)
(* 2. TRIPLE MODULAR REDUNDANT (TMR 2oo3) VOTING ENGINE FOR ZONE TEMPERATURE                         *)
(* ================================================================================================= *)
(* Plausibility boundary validation *)
bTMR_Temp_Ch1_Healthy := (rFurnaceZoneTemp_TMR1 >= 50.0) AND (rFurnaceZoneTemp_TMR1 <= 1250.0);
bTMR_Temp_Ch2_Healthy := (rFurnaceZoneTemp_TMR2 >= 50.0) AND (rFurnaceZoneTemp_TMR2 <= 1250.0);
bTMR_Temp_Ch3_Healthy := (rFurnaceZoneTemp_TMR3 >= 50.0) AND (rFurnaceZoneTemp_TMR3 <= 1250.0);

(* Compute cross-channel absolute deviations *)
rTMR_Temp_Diff12 := ABS(rFurnaceZoneTemp_TMR1 - rFurnaceZoneTemp_TMR2);
rTMR_Temp_Diff23 := ABS(rFurnaceZoneTemp_TMR2 - rFurnaceZoneTemp_TMR3);
rTMR_Temp_Diff31 := ABS(rFurnaceZoneTemp_TMR3 - rFurnaceZoneTemp_TMR1);

(* Run discrepancy persistence timers *)
ton_TempDiscrepancy_Ch1(IN := (rTMR_Temp_Diff12 > TMR_TEMP_MAX_DEVIATION_DEG_C) AND (rTMR_Temp_Diff31 > TMR_TEMP_MAX_DEVIATION_DEG_C), PT := DISCREPANCY_PERSIST_TIME);
ton_TempDiscrepancy_Ch2(IN := (rTMR_Temp_Diff12 > TMR_TEMP_MAX_DEVIATION_DEG_C) AND (rTMR_Temp_Diff23 > TMR_TEMP_MAX_DEVIATION_DEG_C), PT := DISCREPANCY_PERSIST_TIME);
ton_TempDiscrepancy_Ch3(IN := (rTMR_Temp_Diff23 > TMR_TEMP_MAX_DEVIATION_DEG_C) AND (rTMR_Temp_Diff31 > TMR_TEMP_MAX_DEVIATION_DEG_C), PT := DISCREPANCY_PERSIST_TIME);

IF ton_TempDiscrepancy_Ch1.Q THEN bTMR_Temp_Ch1_Healthy := FALSE; dwAlarmBitmask := dwAlarmBitmask OR 16#00000002; END_IF;
IF ton_TempDiscrepancy_Ch2.Q THEN bTMR_Temp_Ch2_Healthy := FALSE; dwAlarmBitmask := dwAlarmBitmask OR 16#00000004; END_IF;
IF ton_TempDiscrepancy_Ch3.Q THEN bTMR_Temp_Ch3_Healthy := FALSE; dwAlarmBitmask := dwAlarmBitmask OR 16#00000008; END_IF;

(* 2oo3 Voting & Fault-Tolerant Arbiter Logic *)
IF bTMR_Temp_Ch1_Healthy AND bTMR_Temp_Ch2_Healthy AND bTMR_Temp_Ch3_Healthy THEN
    (* All three healthy: select exact mathematical median *)
    IF ((rFurnaceZoneTemp_TMR1 >= rFurnaceZoneTemp_TMR2) AND (rFurnaceZoneTemp_TMR1 <= rFurnaceZoneTemp_TMR3)) OR
       ((rFurnaceZoneTemp_TMR1 <= rFurnaceZoneTemp_TMR2) AND (rFurnaceZoneTemp_TMR1 >= rFurnaceZoneTemp_TMR3)) THEN
        rValidatedZoneTemp_degC := rFurnaceZoneTemp_TMR1;
    ELSIF ((rFurnaceZoneTemp_TMR2 >= rFurnaceZoneTemp_TMR1) AND (rFurnaceZoneTemp_TMR2 <= rFurnaceZoneTemp_TMR3)) OR
          ((rFurnaceZoneTemp_TMR2 <= rFurnaceZoneTemp_TMR1) AND (rFurnaceZoneTemp_TMR2 >= rFurnaceZoneTemp_TMR3)) THEN
        rValidatedZoneTemp_degC := rFurnaceZoneTemp_TMR2;
    ELSE
        rValidatedZoneTemp_degC := rFurnaceZoneTemp_TMR3;
    END_IF;
ELSIF bTMR_Temp_Ch1_Healthy AND bTMR_Temp_Ch2_Healthy THEN
    rValidatedZoneTemp_degC := (rFurnaceZoneTemp_TMR1 + rFurnaceZoneTemp_TMR2) * 0.5;
ELSIF bTMR_Temp_Ch2_Healthy AND bTMR_Temp_Ch3_Healthy THEN
    rValidatedZoneTemp_degC := (rFurnaceZoneTemp_TMR2 + rFurnaceZoneTemp_TMR3) * 0.5;
ELSIF bTMR_Temp_Ch3_Healthy AND bTMR_Temp_Ch1_Healthy THEN
    rValidatedZoneTemp_degC := (rFurnaceZoneTemp_TMR3 + rFurnaceZoneTemp_TMR1) * 0.5;
ELSIF bTMR_Temp_Ch1_Healthy THEN
    rValidatedZoneTemp_degC := rFurnaceZoneTemp_TMR1;
    dwAlarmBitmask := dwAlarmBitmask OR 16#00000010; (* Degraded 1-Channel Mode *)
ELSIF bTMR_Temp_Ch2_Healthy THEN
    rValidatedZoneTemp_degC := rFurnaceZoneTemp_TMR2;
    dwAlarmBitmask := dwAlarmBitmask OR 16#00000010;
ELSIF bTMR_Temp_Ch3_Healthy THEN
    rValidatedZoneTemp_degC := rFurnaceZoneTemp_TMR3;
    dwAlarmBitmask := dwAlarmBitmask OR 16#00000010;
ELSE
    (* All temperature channels lost -> Safe emergency shutdown *)
    rValidatedZoneTemp_degC := 999.9;
    dwAlarmBitmask := dwAlarmBitmask OR 16#00000020; (* Critical Total Temperature Loss *)
    iFurnaceState := 90;
END_IF;

(* ================================================================================================= *)
(* 3. TRIPLE MODULAR REDUNDANT (TMR 2oo3) VOTING ENGINE FOR ATMOSPHERE DEW POINT                     *)
(* ================================================================================================= *)
bTMR_Dew_Ch1_Healthy := (rDewPoint_TMR1 >= -85.0) AND (rDewPoint_TMR1 <= 15.0);
bTMR_Dew_Ch2_Healthy := (rDewPoint_TMR2 >= -85.0) AND (rDewPoint_TMR2 <= 15.0);
bTMR_Dew_Ch3_Healthy := (rDewPoint_TMR3 >= -85.0) AND (rDewPoint_TMR3 <= 15.0);

rTMR_Dew_Diff12 := ABS(rDewPoint_TMR1 - rDewPoint_TMR2);
rTMR_Dew_Diff23 := ABS(rDewPoint_TMR2 - rDewPoint_TMR3);
rTMR_Dew_Diff31 := ABS(rDewPoint_TMR3 - rDewPoint_TMR1);

ton_DewDiscrepancy_Ch1(IN := (rTMR_Dew_Diff12 > TMR_DEW_MAX_DEVIATION_DEG_C) AND (rTMR_Dew_Diff31 > TMR_DEW_MAX_DEVIATION_DEG_C), PT := DISCREPANCY_PERSIST_TIME);
ton_DewDiscrepancy_Ch2(IN := (rTMR_Dew_Diff12 > TMR_DEW_MAX_DEVIATION_DEG_C) AND (rTMR_Dew_Diff23 > TMR_DEW_MAX_DEVIATION_DEG_C), PT := DISCREPANCY_PERSIST_TIME);
ton_DewDiscrepancy_Ch3(IN := (rTMR_Dew_Diff23 > TMR_DEW_MAX_DEVIATION_DEG_C) AND (rTMR_Dew_Diff31 > TMR_DEW_MAX_DEVIATION_DEG_C), PT := DISCREPANCY_PERSIST_TIME);

IF ton_DewDiscrepancy_Ch1.Q THEN bTMR_Dew_Ch1_Healthy := FALSE; dwAlarmBitmask := dwAlarmBitmask OR 16#00000040; END_IF;
IF ton_DewDiscrepancy_Ch2.Q THEN bTMR_Dew_Ch2_Healthy := FALSE; dwAlarmBitmask := dwAlarmBitmask OR 16#00000080; END_IF;
IF ton_DewDiscrepancy_Ch3.Q THEN bTMR_Dew_Ch3_Healthy := FALSE; dwAlarmBitmask := dwAlarmBitmask OR 16#00000100; END_IF;

IF bTMR_Dew_Ch1_Healthy AND bTMR_Dew_Ch2_Healthy AND bTMR_Dew_Ch3_Healthy THEN
    IF ((rDewPoint_TMR1 >= rDewPoint_TMR2) AND (rDewPoint_TMR1 <= rDewPoint_TMR3)) OR
       ((rDewPoint_TMR1 <= rDewPoint_TMR2) AND (rDewPoint_TMR1 >= rDewPoint_TMR3)) THEN
        rValidatedDewPoint_degC := rDewPoint_TMR1;
    ELSIF ((rDewPoint_TMR2 >= rDewPoint_TMR1) AND (rDewPoint_TMR2 <= rDewPoint_TMR3)) OR
          ((rDewPoint_TMR2 <= rDewPoint_TMR1) AND (rDewPoint_TMR2 >= rDewPoint_TMR3)) THEN
        rValidatedDewPoint_degC := rDewPoint_TMR2;
    ELSE
        rValidatedDewPoint_degC := rDewPoint_TMR3;
    END_IF;
ELSIF bTMR_Dew_Ch1_Healthy AND bTMR_Dew_Ch2_Healthy THEN
    rValidatedDewPoint_degC := (rDewPoint_TMR1 + rDewPoint_TMR2) * 0.5;
ELSIF bTMR_Dew_Ch2_Healthy AND bTMR_Dew_Ch3_Healthy THEN
    rValidatedDewPoint_degC := (rDewPoint_TMR2 + rDewPoint_TMR3) * 0.5;
ELSIF bTMR_Dew_Ch3_Healthy AND bTMR_Dew_Ch1_Healthy THEN
    rValidatedDewPoint_degC := (rDewPoint_TMR3 + rDewPoint_TMR1) * 0.5;
ELSIF bTMR_Dew_Ch1_Healthy THEN
    rValidatedDewPoint_degC := rDewPoint_TMR1;
    dwAlarmBitmask := dwAlarmBitmask OR 16#00000200;
ELSIF bTMR_Dew_Ch2_Healthy THEN
    rValidatedDewPoint_degC := rDewPoint_TMR2;
    dwAlarmBitmask := dwAlarmBitmask OR 16#00000200;
ELSIF bTMR_Dew_Ch3_Healthy THEN
    rValidatedDewPoint_degC := rDewPoint_TMR3;
    dwAlarmBitmask := dwAlarmBitmask OR 16#00000200;
ELSE
    rValidatedDewPoint_degC := 0.0;
    dwAlarmBitmask := dwAlarmBitmask OR 16#00000400; (* All dewpoint sensors failed *)
END_IF;

(* ================================================================================================= *)
(* 4. THERMODYNAMIC DEW POINT & ELLINGHAM OXIDATION MODEL (Fe/Mn/Si/Cr)                              *)
(* ================================================================================================= *)
(* Magnus-Tetens Formulation for Saturation Water Vapor Pressure over ice/water *)
IF rValidatedDewPoint_degC >= 0.0 THEN
    rSaturationVaporPress_hPa := 6.1078 * EXPT(10.0, (7.5 * rValidatedDewPoint_degC) / (237.3 + rValidatedDewPoint_degC));
ELSE
    (* Saturation over ice below 0 deg C *)
    rSaturationVaporPress_hPa := 6.1078 * EXPT(10.0, (9.5 * rValidatedDewPoint_degC) / (265.5 + rValidatedDewPoint_degC));
END_IF;

(* Convert hPa to Pascal: 1 hPa = 100 Pa *)
rWaterVaporPartialPress_Pa := rSaturationVaporPress_hPa * 100.0;

(* Calculate Ellingham-Richardson thermodynamic oxidation equilibrium log10(P_H2O / P_H2) *)
IF (rAtmosphereH2_pct > 0.5) AND (rWaterVaporPartialPress_Pa > 0.001) THEN
    (* P_H2 partial pressure in Pa, assuming total furnace pressure ~ 101325 + furnace overpressure *)
    rLog10_PH2O_PH2_Ratio := LOG( (rWaterVaporPartialPress_Pa) / ((rAtmosphereH2_pct / 100.0) * (101325.0 + rFurnacePressure_mbar * 100.0)) );
ELSE
    rLog10_PH2O_PH2_Ratio := -1.0;
END_IF;

(* Critical threshold for selective surface oxidation of Mn/Si in AHSS (grade factor dependent) *)
rEquilibriumLogRatio_Limit := -4.2 + (rSteelGradeAlloyFactor * 0.35) - ( (rValidatedZoneTemp_degC - 750.0) / 450.0 );
bAlloyOxidationRisk := (rLog10_PH2O_PH2_Ratio > rEquilibriumLogRatio_Limit);
IF bAlloyOxidationRisk THEN
    dwAlarmBitmask := dwAlarmBitmask OR 16#00000800; (* Bit 11: Steel Surface Oxidation Risk *)
END_IF;

(* ================================================================================================= *)
(* 5. COMBUSTION STOICHIOMETRY & THERMAL NOX (ZELDOVICH MECHANISM) OBSERVER                          *)
(* ================================================================================================= *)
(* Adiabatic flame temperature approximation factoring preheated combustion air & FGR *)
rAdiabaticFlameTemp_K := (rCombAirPreheatTemp_degC + 273.15) + (rFuelGasLowerHeatingVal_MJ_Nm3 * 42.0) - (u2_FGR_Damper * 4.8);

(* Arrhenius reaction rate exponent for thermal NOx formation *)
IF rAdiabaticFlameTemp_K > 1400.0 THEN
    rZeldovichNOxFactor := EXP(-38000.0 / rAdiabaticFlameTemp_K) * 1.85E9;
ELSE
    rZeldovichNOxFactor := 0.0;
END_IF;

(* Simulated dynamic NOx generation rate taking excess air ratio into account *)
rEstimatedNOx_ppm := (rZeldovichNOxFactor * (u1_LambdaTrim - 0.95) * 120.0) / (1.0 + (u2_FGR_Damper * 0.045));
rEstimatedNOx_ppm := LIMIT(0.0, rEstimatedNOx_ppm, 600.0);

(* Mass emission calculation: rho_NOx * V_flue * NOx_ppm * 1e-6 *)
rInstantaneousNOx_kg_h := (rCombAirActualFlow_Nm3h + rFuelGasActualFlow_Nm3h) * (rExhaustNOx_ppm * 1.0E-6) * (NOX_MOLAR_MASS_G_MOL / 22.414);

(* ================================================================================================= *)
(* 6. STRIP THERMAL THROUGHPUT & MASS FLOW FEEDFORWARD CALCULATOR                                    *)
(* ================================================================================================= *)
(* Strip velocity derivative (acceleration) *)
rSpeedAcceleration := (rStripSpeed - rPrevStripSpeed) / rCycleTimeSec;
rPrevStripSpeed    := rStripSpeed;

(* Steel strip thermal absorption demand: P = m_dot * Cp * deltaT *)
(* m_dot [kg/s] = (speed [m/min] / 60) * (width [mm]/1000) * (thickness [mm]/1000) * 7850 kg/m3 *)
rStripHeatAbsorption_kW := ((rStripSpeed / 60.0) * (rStripWidth * 0.001) * (rStripThickness * 0.001) * STEEL_DENSITY_KG_M3)
                            * (STEEL_SPECIFIC_HEAT_J_KG_K * 0.001) * (rSetPointZoneTemp_degC - 25.0);

(* Specific energy consumption in MJ per ton of steel *)
IF (rStripSpeed > 1.0) AND (rStripWidth > 100.0) AND (rStripThickness > 0.1) THEN
    rSpecificEnergy_MJ_ton := (rFuelGasActualFlow_Nm3h * rFuelGasLowerHeatingVal_MJ_Nm3) /
                              (((rStripSpeed / 60.0) * (rStripWidth * 0.001) * (rStripThickness * 0.001) * STEEL_DENSITY_KG_M3 * 3.6) + 0.001);
ELSE
    rSpecificEnergy_MJ_ton := 0.0;
END_IF;

(* ================================================================================================= *)
(* 7. MULTI-VARIABLE (2x2 MIMO) MODEL PREDICTIVE CONTROL (MPC) RECURSIVE ENGINE                      *)
(* ================================================================================================= *)
(*
   Continuous-time physical model discretized at deltaT = rCycleTimeSec:
   State updates:
     x1(k+1) = a11*x1 + a12*x2 + b11*u1 + b12*u2 + e11*d1
     x2(k+1) = a22*x2 + b21*u1 + e21*d1
     x3(k+1) = a33*x3 + b33*u3 + e31*d2
     x4(k+1) = a44*x4 + b43*u3
*)
x1_NOx         := (0.92 * x1_NOx) + (0.015 * x2_TubeThermal) + (45.0 * (u1_LambdaTrim - 1.05)) - (1.2 * u2_FGR_Damper) + (0.008 * rCombAirPreheatTemp_degC);
x2_TubeThermal := (0.985 * x2_TubeThermal) + (0.35 * (rFuelGasActualFlow_Nm3h * 0.01)) - (0.00045 * rStripHeatAbsorption_kW);
x3_MoistureRate:= (0.88 * x3_MoistureRate) - (0.42 * (u3_DryN2_Trim * 0.05)) + (0.15 * rSpeedAcceleration);
x4_AtmoInertia := (0.97 * x4_AtmoInertia) + (0.05 * (rAtmosphereH2_pct - rTargetH2_pct));

(* Process Control Error Tracking *)
rErrorZoneTemp := rSetPointZoneTemp_degC - rValidatedZoneTemp_degC;
rErrorDewPoint := rValidatedDewPoint_degC - rSetPointDewPoint_degC; (* Positive error means too wet! *)
rErrorNOx      := rExhaustNOx_ppm - rNOxPermitCeiling_ppm;           (* Positive error means exceeding limit *)

(* Integral Error Accumulators with Anti-Windup Clamping *)
rIntegralTemp := LIMIT(-500.0, rIntegralTemp + (rErrorZoneTemp * rCycleTimeSec * 0.45), 500.0);
rIntegralDew  := LIMIT(-200.0, rIntegralDew  + (rErrorDewPoint * rCycleTimeSec * 0.25), 200.0);
rIntegralNOx  := LIMIT(-100.0, rIntegralNOx  + (rErrorNOx * rCycleTimeSec * 0.10), 100.0);

(* MPC Receding Horizon Control Law Evaluation *)
(* Manipulated variable 1: Lambda (Air-to-Fuel excess ratio) *)
IF rErrorNOx > 0.0 THEN
    (* Reduce excess air to suppress thermal NOx while monitoring CO ceiling *)
    u1_LambdaTrim := 1.08 - (0.0015 * rErrorNOx) - (0.0005 * rIntegralNOx);
    IF rExhaustCO_ppm > 150.0 THEN
        u1_LambdaTrim := u1_LambdaTrim + 0.02; (* CO limit override *)
    END_IF;
ELSE
    u1_LambdaTrim := 1.08 + (0.0005 * (rSetPointZoneTemp_degC - rValidatedZoneTemp_degC) / 100.0);
END_IF;
u1_LambdaTrim := LIMIT(1.02, u1_LambdaTrim, 1.25);

(* Manipulated variable 2: Flue Gas Recirculation (FGR) Damper Demand [%] *)
u2_FGR_Damper := 10.0 + (0.45 * rExhaustNOx_ppm) + (0.05 * rCombAirPreheatTemp_degC) - (0.15 * rErrorZoneTemp);
u2_FGR_Damper := LIMIT(0.0, u2_FGR_Damper, 65.0);

(* Manipulated variable 3: Dry N2 Sweep / Trimming Injection for Dewpoint Suppression *)
IF rErrorDewPoint > 0.0 THEN
    (* Dew point is higher (wetter) than target: aggressively ramp dry N2 and trim H2 *)
    u3_DryN2_Trim := 40.0 + (12.0 * rErrorDewPoint) + (2.5 * rIntegralDew) + (15.0 * rSteelGradeAlloyFactor);
ELSE
    u3_DryN2_Trim := 10.0 + (1.5 * rErrorDewPoint);
END_IF;
u3_DryN2_Trim := LIMIT(0.0, u3_DryN2_Trim, 100.0);

(* ================================================================================================= *)
(* 8. FINITE STATE MACHINE (10-STAGE DETERMINISTIC REVERSIBLE SEQUENCER)                             *)
(* ================================================================================================= *)
CASE iFurnaceState OF

    0: (* ----------------- IDLE / SAFE PREPARATION STATE ----------------- *)
        bSystemReady                := FALSE;
        bAtmosphereSafe             := FALSE;
        bEmergencyPurgeActive       := FALSE;
        rFuelFlowDemand_Nm3h        := 0.0;
        rAirFlowDemand_Nm3h         := 100.0;
        rFGR_DamperPositionDemand_pct := 0.0;
        rSecondaryAirSplit_pct      := 0.0;
        rDeNOx_ReagentFlowDemand_l_h:= 0.0;
        rH2_TrimmingValveDemand_pct := 0.0;
        rDryN2_PurgeValveDemand_pct := 10.0;
        rCumulativePurgeVolume_Nm3  := 0.0;

        IF bSystemEnable AND bEmergencyStopOk AND bAtmospherePurgePermit THEN
            iFurnaceState := 10; (* Advance to Nitrogen Inerting Purge *)
        END_IF;

    10: (* ---------------- PRE-IGNITION NITROGEN INERTING PURGE ------------ *)
        (* Enforce 5 volume exchanges of pure N2 to displace ambient O2 below 1.0% *)
        bSystemReady                := FALSE;
        bAtmosphereSafe             := FALSE;
        rDryN2_PurgeValveDemand_pct := 85.0;
        rH2_TrimmingValveDemand_pct := 0.0;
        rFuelFlowDemand_Nm3h        := 0.0;
        rAirFlowDemand_Nm3h         := 250.0;
        rAtmosphereExhaustDamper_pct:= 60.0;

        (* Integrate purge flow to calculate exchanged volume *)
        rCumulativePurgeVolume_Nm3 := rCumulativePurgeVolume_Nm3 + (rAtmosphereN2_Flow_Nm3h * (rCycleTimeSec / 3600.0));
        ton_PurgeTimer(IN := TRUE, PT := T#300S);

        IF (rCumulativePurgeVolume_Nm3 >= rRequiredPurgeVolume_Nm3) OR ton_PurgeTimer.Q THEN
            ton_PurgeTimer(IN := FALSE);
            iFurnaceState := 20; (* Advance to TMR Sensor Diagnostic Check *)
        END_IF;

    20: (* ---------------- TMR SENSORS CALIBRATION & INTEGRITY CHECK ------- *)
        bSystemReady := FALSE;
        IF bTMR_Temp_Ch1_Healthy AND bTMR_Temp_Ch2_Healthy AND bTMR_Temp_Ch3_Healthy AND
           bTMR_Dew_Ch1_Healthy AND bTMR_Dew_Ch2_Healthy AND bTMR_Dew_Ch3_Healthy THEN
            iFurnaceState := 30; (* Advance to Radiant Tube Heating *)
        ELSIF (bTMR_Temp_Ch1_Healthy OR bTMR_Temp_Ch2_Healthy OR bTMR_Temp_Ch3_Healthy) AND
              (bTMR_Dew_Ch1_Healthy OR bTMR_Dew_Ch2_Healthy OR bTMR_Dew_Ch3_Healthy) THEN
            iFurnaceState := 70; (* Divert to Degraded Sensor Mode *)
        ELSE
            iFurnaceState := 0;  (* Unrecoverable sensor fault *)
        END_IF;

    30: (* ---------------- RADIANT TUBE SOFT IGNITION & PREHEAT ------------ *)
        bSystemReady := FALSE;
        bAtmosphereSafe := FALSE;
        rFuelFlowDemand_Nm3h := 150.0 + (0.45 * rErrorZoneTemp);
        rAirFlowDemand_Nm3h  := rFuelFlowDemand_Nm3h * STOICHIOMETRIC_AIR_FUEL_RATIO * 1.15;
        rFGR_DamperPositionDemand_pct := 5.0;
        rSecondaryAirSplit_pct := 20.0;

        ton_IgnitionSoak(IN := (rValidatedZoneTemp_degC >= 750.0), PT := T#120S);
        IF ton_IgnitionSoak.Q THEN
            ton_IgnitionSoak(IN := FALSE);
            iFurnaceState := 40; (* Advance to Hydrogen Enrichment *)
        END_IF;

    40: (* ---------------- H2 ENRICHMENT & DEWPOINT SUPPRESSION ------------ *)
        (* Atmosphere temperature exceeds 750 deg C auto-ignition safety threshold (EN 746-2) *)
        bAtmosphereSafe := (rFurnacePressure_mbar >= 0.35) AND (rValidatedZoneTemp_degC >= 750.0);
        IF bAtmosphereSafe THEN
            rH2_TrimmingValveDemand_pct := LIMIT(0.0, (rTargetH2_pct - rAtmosphereH2_pct) * 3.5, 80.0);
            rDryN2_PurgeValveDemand_pct := u3_DryN2_Trim;
        END_IF;

        IF (rAtmosphereH2_pct >= (rTargetH2_pct * 0.90)) AND (rValidatedDewPoint_degC <= rSetPointDewPoint_degC) THEN
            iFurnaceState := 50; (* Advance to Steady State Advanced MIMO MPC *)
        END_IF;

    50: (* ---------------- STEADY-STATE ADVANCED MIMO MPC OPERATION -------- *)
        bSystemReady    := TRUE;
        bAtmosphereSafe := TRUE;

        (* Feedforward + Feedback Heating Demand *)
        rTheoreticalCombAirDemand_Nm3h := rFuelFlowDemand_Nm3h * STOICHIOMETRIC_AIR_FUEL_RATIO * u1_LambdaTrim;
        rFuelFlowDemand_Nm3h := (rStripHeatAbsorption_kW * 0.085) + (2.2 * rErrorZoneTemp) + (0.35 * rIntegralTemp);
        rFuelFlowDemand_Nm3h := LIMIT(50.0, rFuelFlowDemand_Nm3h, 2400.0);

        rAirFlowDemand_Nm3h := rFuelFlowDemand_Nm3h * STOICHIOMETRIC_AIR_FUEL_RATIO * u1_LambdaTrim;
        rAirFlowDemand_Nm3h := LIMIT(400.0, rAirFlowDemand_Nm3h, 28000.0);

        rAirFuelRatioTarget           := u1_LambdaTrim;
        rFGR_DamperPositionDemand_pct := u2_FGR_Damper;
        rSecondaryAirSplit_pct        := LIMIT(15.0, 25.0 + (0.25 * rExhaustNOx_ppm), 55.0);

        (* DeNOx Reagent Injection for peak shaving *)
        IF rExhaustNOx_ppm > (rNOxPermitCeiling_ppm * 0.85) THEN
            rDeNOx_ReagentFlowDemand_l_h := (rExhaustNOx_ppm - (rNOxPermitCeiling_ppm * 0.85)) * 0.35;
        ELSE
            rDeNOx_ReagentFlowDemand_l_h := 0.0;
        END_IF;

        (* Atmosphere Actuators *)
        rH2_TrimmingValveDemand_pct := LIMIT(5.0, (rTargetH2_pct - rAtmosphereH2_pct) * 4.0 + 20.0, 95.0);
        rDryN2_PurgeValveDemand_pct := u3_DryN2_Trim;
        rAtmosphereExhaustDamper_pct := LIMIT(10.0, 25.0 + (rFurnacePressure_mbar - 1.5) * 20.0, 90.0);

        (* Check for line speed dynamic transients *)
        IF ABS(rSpeedAcceleration) > 0.5 THEN
            iFurnaceState := 60; (* Divert to Line Speed Feedforward Acceleration Mode *)
        END_IF;

    60: (* ---------------- LINE SPEED TRANSIENT FEEDFORWARD BOOST --------- *)
        bSystemReady := TRUE;
        (* Apply anticipatory thermal boost to prevent strip under-annealing *)
        rFuelFlowDemand_Nm3h := rFuelFlowDemand_Nm3h + (rSpeedAcceleration * 25.0);
        rFuelFlowDemand_Nm3h := LIMIT(50.0, rFuelFlowDemand_Nm3h, 2400.0);
        rAirFlowDemand_Nm3h  := rFuelFlowDemand_Nm3h * STOICHIOMETRIC_AIR_FUEL_RATIO * u1_LambdaTrim;

        (* Anticipate strip moisture outgassing from higher speed throughput *)
        rDryN2_PurgeValveDemand_pct := LIMIT(0.0, u3_DryN2_Trim + (rSpeedAcceleration * 15.0), 100.0);

        IF ABS(rSpeedAcceleration) <= 0.1 THEN
            iFurnaceState := 50; (* Return to steady-state MPC *)
        END_IF;

    70: (* ---------------- DEGRADED TMR SENSOR TOLERANT MODE -------------- *)
        bSystemReady := TRUE;
        (* Cautious firing rate clamp to protect radiant tubes while instrument degraded *)
        rFuelFlowDemand_Nm3h := LIMIT(50.0, rFuelFlowDemand_Nm3h, 1600.0);
        rAirFlowDemand_Nm3h  := rFuelFlowDemand_Nm3h * STOICHIOMETRIC_AIR_FUEL_RATIO * 1.12;
        rFGR_DamperPositionDemand_pct := 30.0; (* Elevated FGR for conservative low-temperature flame *)
        rDryN2_PurgeValveDemand_pct   := LIMIT(35.0, u3_DryN2_Trim + 20.0, 100.0);

        IF NOT (bTMR_Temp_Ch1_Healthy OR bTMR_Temp_Ch2_Healthy OR bTMR_Temp_Ch3_Healthy) THEN
            iFurnaceState := 90; (* Total instrument loss -> trip *)
        END_IF;

    80: (* ---------------- CONTROLLED LINE STOP & IDLE SOAK --------------- *)
        bSystemReady := FALSE;
        rFuelFlowDemand_Nm3h := 180.0; (* Holding flame *)
        rAirFlowDemand_Nm3h  := 2200.0;
        rFGR_DamperPositionDemand_pct := 10.0;
        rH2_TrimmingValveDemand_pct := 10.0;
        rDryN2_PurgeValveDemand_pct := 15.0;

        IF rStripSpeed > 5.0 THEN
            iFurnaceState := 50;
        END_IF;

    90: (* ---------------- EMERGENCY ATMOSPHERE DELUGE & EXTINCTION -------- *)
        bSystemReady                 := FALSE;
        bAtmosphereSafe              := FALSE;
        bEmergencyPurgeActive        := TRUE;
        rFuelFlowDemand_Nm3h         := 0.0;
        rAirFlowDemand_Nm3h          := 300.0;
        rFGR_DamperPositionDemand_pct:= 0.0;
        rSecondaryAirSplit_pct       := 0.0;
        rDeNOx_ReagentFlowDemand_l_h := 0.0;
        rH2_TrimmingValveDemand_pct  := 0.0;
        rDryN2_PurgeValveDemand_pct  := 100.0; (* Full N2 deluge to inert vessel *)
        rAtmosphereExhaustDamper_pct := 100.0;

        IF bSystemEnable AND bEmergencyStopOk AND (dwAlarmBitmask = 16#00000000) THEN
            iFurnaceState := 0; (* Reset to IDLE *)
        END_IF;

ELSE
    iFurnaceState := 0;
END_CASE;

iCurrentControlState := iFurnaceState;

(* ================================================================================================= *)
(* 9. DIAGNOSTIC WORD & ALARM REGISTER AGGREGATION                                                   *)
(* ================================================================================================= *)
wZoneStatusWord.0 := bSystemReady;
wZoneStatusWord.1 := bAtmosphereSafe;
wZoneStatusWord.2 := bEmergencyPurgeActive;
wZoneStatusWord.3 := bAlloyOxidationRisk;
wZoneStatusWord.4 := (iFurnaceState = 50);
wZoneStatusWord.5 := (iFurnaceState = 60);
wZoneStatusWord.6 := (iFurnaceState = 70);
wZoneStatusWord.7 := (iFurnaceState = 90);
wZoneStatusWord.8 := bTMR_Temp_Ch1_Healthy;
wZoneStatusWord.9 := bTMR_Temp_Ch2_Healthy;
wZoneStatusWord.10 := bTMR_Temp_Ch3_Healthy;
wZoneStatusWord.11 := bTMR_Dew_Ch1_Healthy;
wZoneStatusWord.12 := bTMR_Dew_Ch2_Healthy;
wZoneStatusWord.13 := bTMR_Dew_Ch3_Healthy;
wZoneStatusWord.14 := (rFurnacePressure_mbar >= 0.3);
wZoneStatusWord.15 := (rExhaustNOx_ppm <= rNOxPermitCeiling_ppm);

(* Furnace pressure and emission limit alarms *)
IF rFurnacePressure_mbar < 0.20 THEN
    dwAlarmBitmask := dwAlarmBitmask OR 16#00001000; (* Bit 12: Furnace Sub-atmospheric Pressure Risk *)
END_IF;

IF rExhaustNOx_ppm > rNOxPermitCeiling_ppm THEN
    dwAlarmBitmask := dwAlarmBitmask OR 16#00002000; (* Bit 13: NOx Emission Permit Exceeded *)
END_IF;

IF rExhaustCO_ppm > 500.0 THEN
    dwAlarmBitmask := dwAlarmBitmask OR 16#00004000; (* Bit 14: Incomplete Combustion High CO Hazard *)
END_IF;

IF (rAtmosphereH2_pct > 5.0) AND (rValidatedZoneTemp_degC < 750.0) AND (NOT bAtmosphereSafe) THEN
    dwAlarmBitmask := dwAlarmBitmask OR 16#00008000; (* Bit 15: Hydrogen Deflagration Risk Below Auto-ignition Temp *)
END_IF;

END_FUNCTION_BLOCK
